                items: [prItem(777, { labels: ['pr_approved', 'ai_validating'],
                    headSha: HEAD, branch: 'ai/gh-777' })],
                prComments: [{ body: '🔄 zombie re-dispatch ' + HEAD + ' — zombie 1/3 at ' + t }]
