    var expectedRunName = configFile + ' : ' + ticketKey;
    var expectedRunNameSuffix = ' : ' + ticketKey;
    var statuses = ['queued', 'in_progress', 'waiting', 'pending'];

    for (var i = 0; i < statuses.length; i++) {
